"""
Frontend half of `auth` and `audit_log`:

  src/auth.tsx                 AuthProvider / useAuth / AuthGate (sign-in and
                               first-run setup screens).  Without an `auth`
                               block, useAuth() allows everything.
  src/components/AuditLog.tsx  the `audit_log` activity screen
"""

AUTH_SHADCN = ["button", "card", "input", "label"]
AUDIT_SHADCN = ["badge", "button", "card", "input", "select", "table"]


AUTH_TSX = r'''/**
 * Sign-in, first-run setup and permissions — generated by `mcn build`.
 * Wrap the app in <AuthProvider><AuthGate>…</AuthGate></AuthProvider>
 * (the generated App.tsx does this when your MCN app has an `auth` block).
 */
import { createContext, useCallback, useContext, useEffect, useState } from "react"
import type { FormEvent, ReactNode } from "react"
import { Loader2, LockKeyhole } from "lucide-react"

import { api, getToken, setToken } from "./services/api"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"

export interface User {
  id: number
  name: string
  email: string
  role: string
  active: boolean
}

interface AuthState {
  user: User | null
  permissions: string[] | null          // null = no auth: everything allowed
  can: (endpoint: string) => boolean    // can("/create_lead")
  hasRole: (...roles: string[]) => boolean
  login: (email: string, password: string) => Promise<void>
  setup: (name: string, email: string, password: string) => Promise<void>
  logout: () => void
}

const AuthContext = createContext<AuthState>({
  user: null,
  permissions: null,
  can: () => true,
  hasRole: () => true,
  login: async () => {},
  setup: async () => {},
  logout: () => {},
})

export const useAuth = () => useContext(AuthContext)

const [statusLoading, statusReady, statusSetup, statusSignedOut] = [0, 1, 2, 3]

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [permissions, setPermissions] = useState<string[]>([])
  const [status, setStatus] = useState(statusLoading)

  const signedIn = (data: any) => {
    if (data.token) setToken(data.token)
    setUser(data.user)
    setPermissions(data.permissions ?? [])
    setStatus(statusReady)
  }

  const logout = useCallback(() => {
    setToken(null)
    setUser(null)
    setPermissions([])
    setStatus(statusSignedOut)
  }, [])

  useEffect(() => {
    ;(async () => {
      try {
        if (getToken()) {
          signedIn(await api.get("/me"))
          return
        }
      } catch {
        setToken(null)
      }
      try {
        const s = await api.get("/auth_status")
        setStatus(s.needs_setup ? statusSetup : statusSignedOut)
      } catch {
        setStatus(statusSignedOut)
      }
    })()
    const onUnauthorized = () => logout()
    window.addEventListener("mcn:unauthorized", onUnauthorized)
    return () => window.removeEventListener("mcn:unauthorized", onUnauthorized)
  }, [logout])

  const value: AuthState = {
    user,
    permissions,
    can: (endpoint) => permissions.includes(endpoint.replace(/^\//, "")),
    hasRole: (...roles) => !!user && (roles.length === 0 || roles.includes(user.role)),
    login: async (email, password) => signedIn(await api.post("/login", { email, password })),
    setup: async (name, email, password) => signedIn(await api.post("/setup", { name, email, password })),
    logout,
  }

  return (
    <AuthContext.Provider value={value}>
      <AuthStatusContext.Provider value={status}>{children}</AuthStatusContext.Provider>
    </AuthContext.Provider>
  )
}

const AuthStatusContext = createContext(statusReady)

/** Shows sign-in / setup screens until a user is signed in. */
export function AuthGate({ title, children }: { title: string; children: ReactNode }) {
  const status = useContext(AuthStatusContext)
  if (status === statusLoading) {
    return (
      <div className="flex min-h-screen items-center justify-center text-muted-foreground">
        <Loader2 className="h-6 w-6 animate-spin" />
      </div>
    )
  }
  if (status === statusSetup) return <AuthScreen title={title} mode="setup" />
  if (status === statusSignedOut) return <AuthScreen title={title} mode="login" />
  return <>{children}</>
}

function AuthScreen({ title, mode }: { title: string; mode: "login" | "setup" }) {
  const { login, setup } = useAuth()
  const [name, setName] = useState("")
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [error, setError] = useState("")
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({})
  const [busy, setBusy] = useState(false)

  const submit = async (e: FormEvent) => {
    e.preventDefault()
    setBusy(true)
    setError("")
    setFieldErrors({})
    try {
      if (mode === "setup") await setup(name, email, password)
      else await login(email, password)
    } catch (err: any) {
      setFieldErrors(err?.data?.errors ?? {})
      setError(err instanceof Error ? err.message : String(err))
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-muted/40 p-4">
      <Card className="w-full max-w-sm shadow-lg">
        <CardHeader className="space-y-3 text-center">
          <div className="mx-auto flex h-11 w-11 items-center justify-center rounded-xl bg-primary">
            <LockKeyhole className="h-5 w-5 text-primary-foreground" />
          </div>
          <CardTitle className="text-xl">{mode === "setup" ? "Create the admin account" : `Sign in to ${title}`}</CardTitle>
          <p className="text-sm text-muted-foreground">
            {mode === "setup"
              ? "No users yet. The first account becomes the administrator."
              : "Enter your email and password to continue."}
          </p>
        </CardHeader>
        <CardContent>
          <form onSubmit={submit} className="space-y-4" noValidate>
            {mode === "setup" && (
              <div className="space-y-1.5">
                <Label htmlFor="auth-name">Name</Label>
                <Input id="auth-name" value={name} onChange={(e) => setName(e.target.value)} autoFocus />
                {fieldErrors.name && <p className="text-sm text-destructive">Name {fieldErrors.name}</p>}
              </div>
            )}
            <div className="space-y-1.5">
              <Label htmlFor="auth-email">Email</Label>
              <Input id="auth-email" type="email" autoComplete="email" value={email}
                     onChange={(e) => setEmail(e.target.value)} autoFocus={mode === "login"} />
              {fieldErrors.email && <p className="text-sm text-destructive">Email {fieldErrors.email}</p>}
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="auth-password">Password</Label>
              <Input id="auth-password" type="password" value={password}
                     autoComplete={mode === "setup" ? "new-password" : "current-password"}
                     onChange={(e) => setPassword(e.target.value)} />
              {fieldErrors.password && <p className="text-sm text-destructive">Password {fieldErrors.password}</p>}
            </div>
            {error && !Object.keys(fieldErrors).length && (
              <p className="rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive">{error}</p>
            )}
            <Button type="submit" className="w-full" disabled={busy}>
              {busy && <Loader2 className="mr-1 h-4 w-4 animate-spin" />}
              {mode === "setup" ? "Create account" : "Sign in"}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  )
}
'''


AUDIT_LOG_TSX = r'''/**
 * AuditLog — generated by `mcn build` for `audit_log` in your MCN UI.
 * Who changed what, and when (records from `crud … audit`, sign-ins and
 * user changes).  Safe to customise.
 */
import { Fragment, useCallback, useEffect, useState } from "react"
import { ChevronDown, ChevronLeft, ChevronRight, ChevronUp, Loader2, Search } from "lucide-react"

import { api } from "../services/api"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select"
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table"

interface Entry {
  id: number
  at: string
  user_email: string | null
  action: string
  entity: string
  entity_id: number | null
  summary: string
  changes: Record<string, any>
}

const ALL = "__all__"
const ACTION_STYLE: Record<string, string> = {
  create: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/40 dark:text-emerald-200",
  update: "bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-200",
  delete: "bg-rose-100 text-rose-800 dark:bg-rose-900/40 dark:text-rose-200",
  login: "bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-200",
  login_failed: "bg-amber-100 text-amber-800 dark:bg-amber-900/40 dark:text-amber-200",
}

function show(v: any): string {
  if (v === null || v === undefined || v === "") return "—"
  if (typeof v === "boolean") return v ? "Yes" : "No"
  return String(v)
}

export function AuditLog({ title = "Activity", pageSize = 20 }: { title?: string; pageSize?: number }) {
  const [rows, setRows] = useState<Entry[]>([])
  const [entities, setEntities] = useState<string[]>([])
  const [total, setTotal] = useState(0)
  const [page, setPage] = useState(1)
  const [search, setSearch] = useState("")
  const [query, setQuery] = useState("")
  const [entity, setEntity] = useState(ALL)
  const [open, setOpen] = useState<number | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState("")

  useEffect(() => {
    const t = setTimeout(() => { setQuery(search.trim()); setPage(1) }, 300)
    return () => clearTimeout(t)
  }, [search])

  const load = useCallback(async () => {
    setLoading(true)
    setError("")
    const params = new URLSearchParams({ page: String(page), page_size: String(pageSize) })
    if (query) params.set("search", query)
    if (entity !== ALL) params.set("entity", entity)
    try {
      const data = await api.get(`/list_audit_log?${params}`)
      setRows(data.items ?? [])
      setTotal(data.total ?? 0)
      setEntities(data.entities ?? [])
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e))
    } finally {
      setLoading(false)
    }
  }, [page, pageSize, query, entity])

  useEffect(() => { load() }, [load])
  const pages = Math.max(1, Math.ceil(total / pageSize))

  return (
    <Card className="shadow-sm">
      <CardHeader className="gap-4 space-y-0 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <CardTitle className="text-xl">{title}</CardTitle>
          <p className="mt-1 text-sm text-muted-foreground">Who changed what, and when</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <div className="relative">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search activity…"
                   className="w-56 pl-8" aria-label="Search activity" />
          </div>
          <Select value={entity} onValueChange={(v) => { setEntity(v); setPage(1) }}>
            <SelectTrigger className="w-40" aria-label="Filter by type"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL}>Everything</SelectItem>
              {entities.map((e) => <SelectItem key={e} value={e}>{e}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
      </CardHeader>
      <CardContent>
        {error && <p className="mb-4 rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive">{error}</p>}
        <div className="overflow-hidden rounded-lg border">
          <Table>
            <TableHeader className="bg-muted/50">
              <TableRow>
                <TableHead>When</TableHead>
                <TableHead>Who</TableHead>
                <TableHead>Action</TableHead>
                <TableHead>What</TableHead>
                <TableHead className="w-10" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading && rows.length === 0 ? (
                <TableRow><TableCell colSpan={5} className="h-28 text-center">
                  <Loader2 className="mx-auto h-5 w-5 animate-spin text-muted-foreground" />
                </TableCell></TableRow>
              ) : rows.length === 0 ? (
                <TableRow><TableCell colSpan={5} className="h-28 text-center text-muted-foreground">
                  No activity yet
                </TableCell></TableRow>
              ) : rows.map((r) => (
                <Fragment key={r.id}>
                  <TableRow className="cursor-pointer" onClick={() => setOpen(open === r.id ? null : r.id)}>
                    <TableCell className="whitespace-nowrap text-muted-foreground">{new Date(r.at).toLocaleString()}</TableCell>
                    <TableCell>{r.user_email ?? <span className="text-muted-foreground">system</span>}</TableCell>
                    <TableCell>
                      <Badge variant="outline" className={`border-transparent capitalize ${ACTION_STYLE[r.action] ?? ""}`}>
                        {r.action.replace("_", " ")}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <span className="font-medium">{r.summary}</span>
                      <span className="ml-2 text-xs text-muted-foreground">{r.entity}{r.entity_id ? ` #${r.entity_id}` : ""}</span>
                    </TableCell>
                    <TableCell>{open === r.id ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}</TableCell>
                  </TableRow>
                  {open === r.id && (
                    <TableRow className="bg-muted/30 hover:bg-muted/30">
                      <TableCell colSpan={5}>
                        <dl className="grid gap-x-6 gap-y-1 text-sm sm:grid-cols-[max-content_1fr]">
                          {Object.entries(r.changes ?? {}).map(([k, v]) => (
                            <Fragment key={k}>
                              <dt className="font-medium text-muted-foreground">{k}</dt>
                              <dd>{Array.isArray(v) && v.length === 2 && r.action === "update"
                                ? <><span className="text-muted-foreground line-through">{show(v[0])}</span> → {show(v[1])}</>
                                : show(v)}</dd>
                            </Fragment>
                          ))}
                        </dl>
                      </TableCell>
                    </TableRow>
                  )}
                </Fragment>
              ))}
            </TableBody>
          </Table>
        </div>
        <div className="mt-4 flex items-center justify-between text-sm text-muted-foreground">
          <span>{total} {total === 1 ? "entry" : "entries"}</span>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" disabled={page <= 1} onClick={() => setPage(page - 1)}>
              <ChevronLeft className="h-4 w-4" /> Previous
            </Button>
            <span>Page {page} of {pages}</span>
            <Button variant="outline" size="sm" disabled={page >= pages} onClick={() => setPage(page + 1)}>
              Next <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

export default AuditLog
'''
